                                Official website<span class="visually-hidden"> (opens in a new tab)</span>
                            </a>
                        }
                    </section>
                </div>
            </div>

            @if (topCast().length) {
                <section aria-labelledby="cast-heading" class="cast-section">
                    <h2 id="cast-heading">Top cast</h2>
                    <ul class="cast">
                        @for (person of topCast(); track person.id) {
                            <li class="cast-member">
                                @if (person.profile_path) {
                                    <img [src]="imageBase + '/w185' + person.profile_path" alt=""
                                        width="92" height="138" loading="lazy">
                                } @else {
                                    <div class="no-photo" aria-hidden="true">👤</div>
                                }
                                <strong>{{ person.name }}</strong>
                                @if (person.character) {
                                    <span class="character">as {{ person.character }}</span>
                                }
                            </li>
                        }
                    </ul>
                </section>
            }
        </article>
    } @else if (movie() === null) {
        <p class="empty-state" role="alert">Sorry, we couldn't load this movie. Please try again later.</p>
    } @else {
        <p class="loading" role="status">Loading movie…</p>
    }
</div>

